# Uses a tkinter directory picker to select the folder containing
# maple_summary.csv and maple_results.csv from a MaplePy batch run.

# maplepy package: no folder dialog; the folder is passed in

# ── Where the MaplePy output is ───────────────────────────────────────────
#
# v1.2.5: running this notebook twice in one kernel could sit on this cell
# for minutes with nothing on screen. It is not the figures and it is not the
# CSVs: it is THIS DIALOG. A second Tk root in one process opens a dialog
# that, on Windows, frequently lands BEHIND the browser, and the cell then
# waits for a click on a window nobody can see. Restarting the kernel cures
# it, which is exactly what a hidden modal looks like.
#
# MaplePy's own picker passes parent=root and this one did not. It does now,
# with an update() either side so Tk actually maps the window, and the notice
# below is printed BEFORE the dialog blocks so a hang is diagnosable.
#
# Better still: set MAPLE_DIR_OVERRIDE and no dialog opens at all.
MAPLE_DIR_OVERRIDE = _HOPPER_RUN_DIRECTORY   # maplepy package: the folder passed in
#      # e.g. r"path/to/outputs_YYYYMMDD_HHMMSS"

if MAPLE_DIR_OVERRIDE:
    MAPLE_DIR = str(MAPLE_DIR_OVERRIDE)
    print(f"Using MAPLE_DIR_OVERRIDE, no dialog: {MAPLE_DIR}")
else:
    print("Opening a folder picker. If nothing appears, look BEHIND this "
          "window - a second Tk dialog in one kernel often opens there. "
          "Set MAPLE_DIR_OVERRIDE above to skip the dialog entirely.")
    root = tk.Tk()
    root.withdraw()
    root.update()
    root.attributes('-topmost', True)
    root.lift()
    root.focus_force()

    MAPLE_DIR = filedialog.askdirectory(
        title="Select folder containing MaplePy output CSVs "
              "(maple_summary.csv and maple_results.csv)",
        parent=root
    )
    root.update()
    root.destroy()

if not MAPLE_DIR:
    raise FileNotFoundError(
        "No directory selected. Re-run this cell and choose the "
        "folder containing your MaplePy output CSVs."
    )

MAPLE_DIR = Path(MAPLE_DIR)
print(f"Selected directory: {MAPLE_DIR}")

# ── Locate CSVs ──────────────────────────────────────────────────────────
summary_csv = MAPLE_DIR / "maple_summary.csv"
results_csv = MAPLE_DIR / "maple_results.csv"

if not summary_csv.exists():
    # Check for outputs_* subdirectories (MaplePy timestamped folders)
    output_dirs = sorted(MAPLE_DIR.glob('outputs_*'), reverse=True)
    if output_dirs:
        MAPLE_DIR = output_dirs[0]
        summary_csv = MAPLE_DIR / 'maple_summary.csv'
        results_csv = MAPLE_DIR / 'maple_results.csv'
        print(f"  Using most recent output: {MAPLE_DIR.name}")

if not summary_csv.exists():
    raise FileNotFoundError(
        f"maple_summary.csv not found in {MAPLE_DIR}.\n"
        f"Run MaplePy batch processing (Section 5 or 7) first."
    )
if not results_csv.exists():
    raise FileNotFoundError(
        f"maple_results.csv not found in {MAPLE_DIR}.\n"
        f"Run MaplePy batch processing (Section 5 or 7) first."
    )

